/* ==========================================================
   Lumyna Flow — página de vendas
   ========================================================== */

/* >>> Contato dos botões de ação <<<
   Número com código do país (55) + DDD + número, só dígitos.
   A mensagem abaixo é a que já vai escrita quando o cliente abre o WhatsApp. */
const CONFIG = {
  whatsappNumber: "5548999116469",
  message: "olá, quero garantir meu acesso no lumyna flow",
};

function init() {
  "use strict";

  var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var canHover = window.matchMedia("(hover: hover) and (pointer: fine)").matches;

  // ---------- Botões de WhatsApp ----------
  var waUrl =
    "https://wa.me/" + CONFIG.whatsappNumber + "?text=" + encodeURIComponent(CONFIG.message);

  document.querySelectorAll("[data-cta]").forEach(function (el) {
    el.setAttribute("href", waUrl);
    el.setAttribute("target", "_blank");
    el.setAttribute("rel", "noopener noreferrer");
  });

  // ---------- Topo, barra de progresso e botão flutuante ----------
  var topbar = document.getElementById("topbar");
  var progress = document.getElementById("progress");
  var fab = document.getElementById("fab");
  var ticking = false;

  function onScroll() {
    var y = window.scrollY;
    var max = document.documentElement.scrollHeight - window.innerHeight;
    topbar.classList.toggle("is-solid", y > 80);
    progress.style.setProperty("--p", max > 0 ? Math.min(y / max, 1) : 0);
    fab.classList.toggle("is-in", y > 240);
    ticking = false;
  }
  window.addEventListener(
    "scroll",
    function () {
      if (!ticking) {
        ticking = true;
        requestAnimationFrame(onScroll);
      }
    },
    { passive: true }
  );
  onScroll();

  // ---------- Revelar elementos ao rolar ----------
  document.querySelectorAll("[data-stagger]").forEach(function (group) {
    Array.prototype.forEach.call(group.children, function (child, i) {
      child.style.setProperty("--d", i * 0.09 + "s");
    });
  });

  var revealEls = document.querySelectorAll("[data-reveal]");

  function reveal(el) {
    el.classList.add("is-visible");
    // depois da entrada, libera as transições normais (hover etc.)
    setTimeout(function () {
      el.removeAttribute("data-reveal");
      el.style.removeProperty("--d");
    }, 2600);
  }

  if ("IntersectionObserver" in window && !reduceMotion) {
    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            reveal(entry.target);
            io.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.18, rootMargin: "0px 0px -6% 0px" }
    );
    revealEls.forEach(function (el) {
      io.observe(el);
    });
  } else {
    revealEls.forEach(function (el) {
      el.classList.add("is-visible");
    });
  }

  // ---------- Hero: luz que segue o mouse e vídeo que inclina ----------
  var hero = document.getElementById("hero");
  var tilt = document.getElementById("tilt");

  if (canHover && !reduceMotion) {
    hero.addEventListener("mousemove", function (e) {
      var r = hero.getBoundingClientRect();
      hero.style.setProperty("--mx", e.clientX - r.left + "px");
      hero.style.setProperty("--my", e.clientY - r.top + "px");
    });

    tilt.addEventListener("mousemove", function (e) {
      var r = tilt.getBoundingClientRect();
      var x = (e.clientX - r.left) / r.width;
      var y = (e.clientY - r.top) / r.height;
      tilt.style.setProperty("--ry", (x - 0.5) * 12 + "deg");
      tilt.style.setProperty("--rx", (0.5 - y) * 10 + "deg");
    });
    tilt.addEventListener("mouseleave", function () {
      tilt.style.setProperty("--ry", "0deg");
      tilt.style.setProperty("--rx", "0deg");
    });
  }

  // ---------- Vídeo ----------
  var video = document.getElementById("demo");
  var playBtn = document.getElementById("playBtn");
  var frame = document.getElementById("mediaFrame");

  // Vídeo embutido no código (base64 -> Blob), sem arquivo externo
  try {
    var bin = atob(VIDEO_DATA);
    var bytes = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    video.src = URL.createObjectURL(new Blob([bytes], { type: "video/mp4" }));
  } catch (err) {}

  playBtn.addEventListener("click", function () {
    video.controls = true;
    frame.classList.add("is-playing");
    var p = video.play();
    if (p && typeof p.catch === "function") {
      p.catch(function () {
        frame.classList.remove("is-playing");
        video.controls = false;
      });
    }
  });

  video.addEventListener("ended", function () {
    video.controls = false;
    video.currentTime = 0;
    frame.classList.remove("is-playing");
  });

  // ---------- Ano do rodapé ----------
  var year = document.getElementById("year");
  if (year) year.textContent = new Date().getFullYear();
}

/* ==========================================================
   VÍDEO EMBUTIDO (base64) — não edite esta linha.
   Para trocar o vídeo, substitua o conteúdo entre as aspas.
   ========================================================== */
const VIDEO_DATA = "";

init();
